from pathlib import Path
import html,json,re
import mistune
root=Path(__file__).resolve().parents[1]
source=(root/'SKILL.md').read_text(encoding='utf-8')
changelog=(root/'CHANGELOG.md').read_text(encoding='utf-8')
version=re.search(r'^version:\s*(.+)$', source, re.M)
version=version.group(1).strip() if version else 'latest'
# Strip YAML front matter only from rendered site; copied markdown is complete original.
body=re.sub(r'^---\n.*?\n---\n','',source,count=1,flags=re.S)
render=mistune.create_markdown(plugins=['table','strikethrough','url'])
content=render(body)
changes=render(changelog)
page=r'''<!DOCTYPE html><html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="小微 Few-shot 标点与 Markdown 格式规范最新版，含正反例、执行流程与更新记录。"><title>小微 Few-shot 格式规范 · 最新版</title><style>
:root{color-scheme:light;font-family:Inter,-apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",sans-serif;background:#f6f7fb;color:#17212f}*{box-sizing:border-box}body{margin:0}a{color:#235bbb}header{background:#fff;border-bottom:1px solid #e7e9ee;position:sticky;top:0;z-index:2}.top{max-width:1120px;margin:auto;padding:15px 24px;display:flex;align-items:center;gap:14px;justify-content:space-between}.brand{font-size:15px;font-weight:750;letter-spacing:.01em}.pill{display:inline-block;background:#eef6f0;color:#247048;font-size:12px;padding:4px 9px;border-radius:24px}.actions{display:flex;gap:8px;flex-wrap:wrap}button,.btn{cursor:pointer;border:1px solid #d5dbe4;color:#263344;background:white;border-radius:9px;padding:10px 13px;font:inherit;font-size:13px;text-decoration:none}button.primary{background:#214eab;color:#fff;border-color:#214eab}button:hover,.btn:hover{filter:brightness(.96)}.wrap{max-width:1120px;margin:36px auto;display:grid;grid-template-columns:220px minmax(0,1fr);gap:24px;padding:0 24px}aside{align-self:start;position:sticky;top:93px;font-size:13px;color:#6b7280}aside a{display:block;padding:7px 0;color:#566277;text-decoration:none}aside a:hover{color:#235bbb}.main{min-width:0}.hero{margin-bottom:24px}.eyebrow{font-size:13px;color:#677486;margin-bottom:8px}.hero h1{font-size:30px;line-height:1.3;margin:0 0 12px}.sub{color:#596778;line-height:1.8;font-size:14px}.sheet{background:#fff;border:1px solid #e7eaf0;border-radius:15px;padding:36px 42px;box-shadow:0 6px 24px #162b5310}article{font-size:15px;line-height:1.85;overflow-wrap:anywhere}article h1{font-size:23px;margin:4px 0 20px}article h2{font-size:21px;margin-top:42px;padding-top:12px;border-top:1px solid #eceef2}article h3{font-size:17px;margin-top:26px}article p,article li{line-height:1.9}article blockquote{border-left:3px solid #aabce0;padding-left:15px;margin-left:0;color:#536179}article code{font-family:ui-monospace,SFMono-Regular,Consolas,monospace;background:#f2f4f7;padding:2px 5px;border-radius:4px;font-size:.91em}article pre{background:#f4f6fa;border:1px solid #e8ebf1;border-radius:10px;padding:16px;white-space:pre-wrap;overflow:auto}article pre code{padding:0;background:transparent}article table{border-collapse:collapse;width:100%;display:block;overflow:auto}article th,article td{border:1px solid #e5e8ee;padding:8px 12px;text-align:left}article th{background:#f6f8fb}.foot{font-size:12px;color:#667181;margin-top:24px}.toast{position:fixed;bottom:24px;left:50%;transform:translateX(-50%);background:#182840;color:white;padding:11px 16px;border-radius:10px;display:none;z-index:3}details{margin-top:26px;border:1px solid #e8ebf1;background:white;border-radius:12px;padding:14px 22px}summary{cursor:pointer;font-weight:650}#changelog{line-height:1.8;font-size:14px}@media(max-width:800px){.wrap{display:block;margin-top:22px;padding:0 12px}aside{display:none}.sheet{padding:22px 18px}.hero h1{font-size:24px}.top{padding:12px;flex-direction:column;align-items:stretch}.actions{justify-content:flex-start}}
</style></head><body><header><div class="top"><div class="brand">小微 / Few-shot 规范 <span class="pill">最新版 · v__VERSION__</span></div><div class="actions"><button class="primary" id="copy">复制完整 SKILL.md</button><a class="btn" href="./SKILL.md" download>下载 Markdown</a><button id="share">复制页面链接</button></div></div></header><div class="wrap"><aside><strong>目录</strong><nav id="nav"></nav><hr style="border:0;border-top:1px solid #eee"><a href="#updates">版本更新</a></aside><main class="main"><div class="hero"><div class="eyebrow">持续维护 · 单一规范源 · 可复制</div><h1>小微 Few-shot 标点与 Markdown 格式规范</h1><div class="sub">所有规则、正反例和审校流程以本页为准。每次发布后，固定链接展示最新版本。复制按钮包含完整 Skill 正文（包括元信息）。</div></div><div class="sheet"><article id="content">__CONTENT__</article></div><details id="updates"><summary>版本更新记录 · CHANGELOG</summary><div id="changelog">__CHANGES__</div></details><p class="foot">如已下载或复制 Skill 到其他地方，该副本不会自动更新；再次打开本页重新复制即可获取最新版本。</p></main></div><div class="toast" id="toast" role="status"></div><script>
const RAW=__RAW__;
const toast=(msg)=>{const x=document.getElementById('toast');x.textContent=msg;x.style.display='block';setTimeout(()=>x.style.display='none',2300)};
async function copy(text){try{await navigator.clipboard.writeText(text);toast('已复制到剪贴板')}catch(e){const t=document.createElement('textarea');t.value=text;document.body.append(t);t.select();const ok=document.execCommand('copy');t.remove();toast(ok?'已复制到剪贴板':'复制失败，请使用下载按钮')}}
document.getElementById('copy').addEventListener('click',()=>copy(RAW));document.getElementById('share').addEventListener('click',()=>copy(location.href.split('#')[0]));
const nav=document.getElementById('nav');document.querySelectorAll('#content h2').forEach((h,i)=>{h.id='section-'+i;let a=document.createElement('a');a.href='#'+h.id;a.textContent=h.textContent;nav.append(a)});
</script></body></html>'''
page=page.replace('__VERSION__',html.escape(version)).replace('__CONTENT__',content).replace('__CHANGES__',changes).replace('__RAW__',json.dumps(source,ensure_ascii=False).replace('</','<\\/'))
out=root/'_site';out.mkdir(exist_ok=True)
(out/'index.html').write_text(page,encoding='utf-8')
(out/'SKILL.md').write_text(source,encoding='utf-8')
print(f'Built {out / "index.html"} (version {version})')
